<script setup>import {computed,onMounted,reactive,ref} from 'vue';import MDialog from '../../components/mds/MDialog.vue';import MEmptyState from '../../components/mds/MEmptyState.vue';import MMobileTopBar from '../../components/mds/MMobileTopBar.vue';import MSpinner from '../../components/mds/MSpinner.vue';import {HostSurface} from '../../platform/host-adapter.mjs';import {createAdminApi} from './domain/admin-api.mjs';import {adminAuditViewModel,adminUsersViewModel} from './domain/admin-view.mjs';import AdminAuditDesktop from './desktop/AdminAuditDesktop.vue';import AdminUserFormDesktop from './desktop/AdminUserFormDesktop.vue';import AdminUsersDesktop from './desktop/AdminUsersDesktop.vue';import AdminAuditMobile from './mobile/AdminAuditMobile.vue';import AdminUserFormMobile from './mobile/AdminUserFormMobile.vue';import AdminUsersMobile from './mobile/AdminUsersMobile.vue';const props=defineProps({surface:String,adapter:Object,hostUnavailable:Boolean});const emit=defineEmits(['back']);const api=createAdminApi();const isNative=computed(()=>props.surface===HostSurface.NATIVE);const safeArea=ref(props.adapter?.getSafeArea?.()||{});const safeAreaStyle=computed(()=>Object.fromEntries(['top','right','bottom','left'].flatMap((side)=>Number.isFinite(Number(safeArea.value?.[side]))?[[`--mds-mobile-safe-${side}`,`${Number(safeArea.value[side])}px`]]:[])));const state=reactive({phase:'loading',mode:'users',rows:[],roles:[],auditRows:[],currentUser:null,permissions:null,editingUser:null,saving:false,formError:'',deleteTarget:null,deleting:false,error:null});const isSuperAdmin=computed(()=>state.currentUser?.role==='super_admin');const canViewAudit=computed(()=>isSuperAdmin.value);const canCreate=computed(()=>state.permissions?.modules?.admin?.includes('create')===true);const canEditModule=computed(()=>state.permissions?.modules?.admin?.includes('edit')===true);const canDeleteModule=computed(()=>state.permissions?.modules?.admin?.includes('delete')===true);const isPrivileged=(user)=>['admin','super_admin'].includes(user?.role);function canEditUser(user){return canEditModule.value&&(isSuperAdmin.value||!isPrivileged(user)||Number(user?.id)===Number(state.currentUser?.id));}function canDeleteUser(user){return canDeleteModule.value&&Number(user?.id)!==Number(state.currentUser?.id)&&(isSuperAdmin.value||!isPrivileged(user));}const roleOptions=computed(()=>{if(isSuperAdmin.value)return state.roles;const selfId=Number(state.editingUser?.id);if(selfId===Number(state.currentUser?.id))return state.roles.filter((option)=>option.value===state.currentUser?.role);return state.roles.filter((option)=>['viewer','executor'].includes(option.value));});async function load(){if(props.hostUnavailable){state.phase='error';state.error={status:503,message:'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.'};return;}state.phase='loading';try{const [users,session]=await Promise.all([api.getUsers(),api.getCurrentUser()]);const model=adminUsersViewModel(users);state.rows=model.rows;state.roles=model.roles;state.currentUser=session?.user||null;state.permissions=session?.permissions||null;state.mode='users';state.phase='ready';}catch(error){state.phase='error';state.error=error;}}async function openAudit(){if(!canViewAudit.value)return;state.phase='loading';try{state.auditRows=adminAuditViewModel(await api.getAudit()).rows;state.mode='audit';state.phase='ready';}catch(error){state.phase='error';state.error=error;}}function startCreate(){if(!canCreate.value)return;state.editingUser=null;state.formError='';state.mode='user-create';}function startEdit(user){if(!canEditUser(user))return;state.editingUser=user;state.formError='';state.mode='user-edit';}async function saveUser(input){state.saving=true;state.formError='';try{await api.saveUser(input,state.editingUser?.id);await load();}catch(error){state.formError=error.message;}finally{state.saving=false;}}async function deleteUser(){const user=state.deleteTarget;if(!canDeleteUser(user))return;state.deleting=true;try{await api.deleteUser(user.id);state.deleteTarget=null;await load();}catch(error){state.deleteTarget=null;state.phase='error';state.error=error;}finally{state.deleting=false;}}function leaveAudit(){state.mode='users';}function leaveForm(){state.editingUser=null;state.formError='';state.mode='users';}function back(){if(state.mode==='audit')return leaveAudit();if(['user-create','user-edit'].includes(state.mode))return leaveForm();if(isNative.value&&props.adapter)return props.adapter.goBack({reason:'admin-users'});emit('back');}onMounted(load);</script>
<template><div v-if="state.phase==='loading'" :class="isNative?'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]':'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'"><MSpinner :size="28"/></div><section v-else-if="state.phase==='error'" :class="isNative?'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]':'min-h-[360px] bg-[var(--mds-bg-page)]'"><MMobileTopBar v-if="isNative" title="Quản trị hệ thống" @back="back"/><MEmptyState :title="state.error.status===403?'Bạn không có quyền quản trị':'Không thể mở quản trị hệ thống'" :description="state.error.message"/></section><AdminAuditMobile v-else-if="isNative&&state.mode==='audit'" :rows="state.auditRows" :safe-area-style="safeAreaStyle" @back="leaveAudit"/><AdminUserFormMobile v-else-if="isNative&&['user-create','user-edit'].includes(state.mode)" :record="state.editingUser" :editing="state.mode==='user-edit'" :saving="state.saving" :error="state.formError" :role-options="roleOptions" :safe-area-style="safeAreaStyle" @cancel="leaveForm" @save="saveUser"/><AdminUsersMobile v-else-if="isNative" :rows="state.rows" :safe-area-style="safeAreaStyle" :can-view-audit="canViewAudit" :can-create="canCreate" :can-edit="canEditUser" :can-delete="canDeleteUser" @back="back" @audit="openAudit" @create="startCreate" @edit="startEdit" @delete="state.deleteTarget=$event"/><AdminAuditDesktop v-else-if="state.mode==='audit'" :rows="state.auditRows" @back="leaveAudit"/><AdminUserFormDesktop v-else-if="['user-create','user-edit'].includes(state.mode)" :record="state.editingUser" :editing="state.mode==='user-edit'" :saving="state.saving" :error="state.formError" :role-options="roleOptions" @cancel="leaveForm" @save="saveUser"/><AdminUsersDesktop v-else :rows="state.rows" :can-view-audit="canViewAudit" :can-create="canCreate" :can-edit="canEditUser" :can-delete="canDeleteUser" @audit="openAudit" @create="startCreate" @edit="startEdit" @delete="state.deleteTarget=$event"/><MDialog :model-value="Boolean(state.deleteTarget)" title="Xóa người dùng?" type="danger" confirm-text="Xóa người dùng" @update:model-value="!$event&&(state.deleteTarget=null)" @confirm="deleteUser"><p>Người dùng <strong>{{ state.deleteTarget?.username }}</strong> sẽ bị xóa vĩnh viễn. Máy chủ sẽ kiểm tra lại quyền trước khi thực hiện.</p></MDialog></template>
